import { z } from "zod";

import { isoInstantSchema, opaqueIdSchema } from "./enums.js";
import { polygonGeometrySchema } from "./geometry.js";
import { pageMetaSchema } from "./page.js";
import { envelopeSchema } from "./response.js";

/**
 * Field contracts (`docs/architecture/farm-field-domain-contracts.md` §6.2, §7).
 *
 * A Field has exactly two writable properties. `farmId` is write-once and only on
 * create — the domain contract has no move-to-another-farm operation — and
 * `areaHa` is generated by PostgreSQL, so neither appears in an update.
 *
 * Nothing here is nullable: the database marks `name` and `geom` `NOT NULL`, and
 * the domain contract provides no "clear" semantics for either. PATCH is therefore
 * "absent means unchanged" with no way to erase a property, which is why the update
 * schema is a partial rather than a set of nullable fields.
 */

/** Path parameter, validated before it can become a cast in SQL. */
export const fieldIdSchema = z.uuid();
export type FieldId = z.infer<typeof fieldIdSchema>;

export const fieldCreateSchema = z.strictObject({
  // The parent is part of create only. Its own not-found semantics are the Farm's.
  farmId: z.uuid(),
  name: z.string().trim().min(1).max(100),
  geometry: polygonGeometrySchema,
});
export type FieldCreateRequest = z.infer<typeof fieldCreateSchema>;

/**
 * `farmId` is absent on purpose: moving a field between farms is not a 4.x
 * operation, and accepting the key would either be ignored (a lie) or silently
 * re-parent the row (a capability the domain does not have).
 */
export const fieldUpdateSchema = z
  .strictObject({
    name: z.string().trim().min(1).max(100),
    geometry: polygonGeometrySchema,
  })
  .partial()
  .refine((value) => Object.keys(value).length > 0, { message: "at least one field" });
export type FieldUpdateRequest = z.infer<typeof fieldUpdateSchema>;

/**
 * The public resource. `geometry` is what PostgreSQL stored, re-serialised by
 * `ST_AsGeoJSON`, not an echo of the request. No `userId`, no `deletedAt`, and none
 * of the eight agronomic columns (`Q4`).
 */
export const fieldSchema = z.strictObject({
  id: opaqueIdSchema,
  farmId: opaqueIdSchema,
  name: z.string().min(1),
  geometry: polygonGeometrySchema,
  areaHa: z.number().positive(),
  createdAt: isoInstantSchema,
  updatedAt: isoInstantSchema,
});
export type Field = z.infer<typeof fieldSchema>;

export const fieldSortSchema = z.enum([
  "name",
  "-name",
  "createdAt",
  "-createdAt",
  "updatedAt",
  "-updatedAt",
  "areaHa",
  "-areaHa",
]);
export type FieldSort = z.infer<typeof fieldSortSchema>;

/**
 * The collection is flat (`Q3`), so `farmId` is an optional filter rather than a
 * path segment. Supplying it scopes the page to one parent and gives that parent
 * the Farm not-found semantics; omitting it lists the tenant's fields.
 */
export const fieldListQuerySchema = z.strictObject({
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(100).default(20),
  sort: fieldSortSchema.default("-createdAt"),
  farmId: z.uuid().optional(),
});
export type FieldListQuery = z.infer<typeof fieldListQuerySchema>;

export const fieldEnvelopeSchema = envelopeSchema(fieldSchema);
export const fieldListEnvelopeSchema = envelopeSchema(z.array(fieldSchema), pageMetaSchema);
